 private function deferralWorkflow(string$status):array{DB::table('users')->insert(['user_id'=>200]);DB::table('academic_programs')->insert(['academic_program_id'=>10]);DB::table('courses')->insert(['course_id'=>10]);DB::table('course_offerings')->insert(['course_offering_id'=>10]);DB::table('supplementary_exam_periods')->insert(['supplementary_exam_period_id'=>10,'academic_year_id'=>10,'semester_id'=>10,'status'=>$status,'created_at'=>now(),'updated_at'=>now()]);DB::table('supplementary_exam_offerings')->insert(['supplementary_exam_offering_id'=>10,'supplementary_exam_period_id'=>10,'academic_program_id'=>10,'course_id'=>10,'status'=>'open','opened_by_user_id'=>200,'opened_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('registration_statuses')->insert(['registration_status_id'=>1,'status_code'=>'registered']);DB::table('student_course_registrations')->insert(['student_course_registration_id'=>10,'student_id'=>10,'course_offering_id'=>10,'registration_status_id'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('supplementary_exam_offering_sources')->insert(['supplementary_exam_offering_id'=>10,'course_offering_id'=>10,'created_at'=>now()]);DB::table('grade_components')->insert(['course_offering_id'=>10,'component_type'=>'theoretical','is_required'=>1]);DB::table('supplementary_exam_theoretical_deferrals')->insert(['supplementary_exam_theoretical_deferral_id'=>10,'supplementary_exam_offering_id'=>10,'student_course_registration_id'=>10,'status'=>'declared','current_slot'=>1,'declared_by_user_id'=>200,'declared_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$registration=StudentCourseRegistration::query()->findOrFail(10);return[new SupplementaryExamEligibilityService(Mockery::mock(\App\Services\GradeService::class)),$registration];}
 public function test_phase4_eligible_student_registration_persists_current_row_and_event():void{[$service,$actor,$offering,$registration]=$this->workflow(true);$row=$service->registerSelf($actor,$offering,$registration);$this->assertSame('registered',$row->status);$this->assertSame(1,(int)$row->current_slot);$this->assertSame('student_self',$row->registration_channel);$this->assertDatabaseHas('supplementary_exam_registration_events',['supplementary_exam_registration_id'=>$row->getKey(),'event_type'=>'registered']);}
 public function test_phase4_ineligible_student_registration_is_rejected_without_row():void{[$service,$actor,$offering,$registration]=$this->workflow(false);try{$service->registerSelf($actor,$offering,$registration);$this->fail('Expected rejection');}catch(GradeException$e){$this->assertSame('supplementary_exam_registration_not_eligible',$e->errorCode);}$this->assertDatabaseCount('supplementary_exam_registrations',0);}
 public function test_phase4_wrong_source_is_rejected_without_registration():void{[$service,$actor,$offering,$registration]=$this->workflow(true);DB::table('supplementary_exam_offering_sources')->delete();try{$service->registerSelf($actor,$offering,$registration);$this->fail('Expected source rejection');}catch(GradeException$e){$this->assertSame('supplementary_exam_registration_source_invalid',$e->errorCode);}$this->assertDatabaseCount('supplementary_exam_registrations',0);}
 public function test_phase4_closed_window_blocks_cancellation():void{[$service,$actor,$offering,$registration]=$this->workflow(true);$row=$service->registerSelf($actor,$offering,$registration);DB::table('supplementary_exam_periods')->where('supplementary_exam_period_id',1)->update(['status'=>'registration_closed']);$this->expectException(GradeException::class);$service->cancelSelf($actor,$row->getKey(),null);}
 public function test_phase4_summer_fourth_registration_is_rejected_and_count_remains_three():void{[$service,$actor]=$this->workflow(true,3,4);for($i=1;$i<=3;$i++)$service->registerSelf($actor,$i,$i);try{$service->registerSelf($actor,4,4);$this->fail('Expected summer limit');}catch(GradeException$e){$this->assertSame('supplementary_exam_summer_limit_reached',$e->errorCode);}$this->assertSame(3,DB::table('supplementary_exam_registrations')->where('status','registered')->where('current_slot',1)->count());}
 public function test_phase4_cancellation_frees_summer_slot_and_preserves_history():void{[$service,$actor]=$this->workflow(true,3,4);$rows=[];for($i=1;$i<=3;$i++)$rows[]=$service->registerSelf($actor,$i,$i);$service->cancelSelf($actor,$rows[1]->getKey(),null);$replacement=$service->registerSelf($actor,4,4);$this->assertSame('registered',$replacement->status);$this->assertDatabaseHas('supplementary_exam_registrations',['supplementary_exam_registration_id'=>$rows[1]->getKey(),'status'=>'cancelled','current_slot'=>null]);$this->assertDatabaseHas('supplementary_exam_registration_events',['supplementary_exam_registration_id'=>$rows[1]->getKey(),'event_type'=>'cancelled']);}
 public function test_phase4_closed_window_blocks_self_registration():void{[$service,$actor,$offering,$registration]=$this->workflow(true,3,1,'registration_closed');$this->expectException(GradeException::class);$service->registerSelf($actor,$offering,$registration);}
 public function test_phase4_window_open_persists_transition_and_audit_event():void{[$service,$actor]=$this->windowWorkflow(true);$period=$service->open($actor,30);$this->assertSame('registration_open',$period->status);$this->assertDatabaseHas('supplementary_exam_period_events',['supplementary_exam_period_id'=>30,'event_type'=>'registration_opened','from_status'=>'announced','to_status'=>'registration_open']);}
 public function test_phase4_window_open_without_university_scope_is_rejected_atomically():void{[$service,$actor]=$this->windowWorkflow(false);try{$service->open($actor,30);$this->fail('Expected scope rejection');}catch(GradeException$e){$this->assertSame('supplementary_exam_registration_out_of_scope',$e->errorCode);}$this->assertDatabaseHas('supplementary_exam_periods',['supplementary_exam_period_id'=>30,'status'=>'announced']);$this->assertDatabaseMissing('supplementary_exam_period_events',['supplementary_exam_period_id'=>30,'event_type'=>'registration_opened']);}
 public function test_phase4_window_close_persists_transition_and_audit_event():void{[$service,$actor]=$this->windowWorkflow(true);$this->seedWindowTarget();$service->open($actor,30);$this->seedWindowRegistration(30,30);$period=$service->close($actor,30);$this->assertSame('registration_closed',$period->status);$this->assertDatabaseHas('supplementary_exam_period_events',['supplementary_exam_period_id'=>30,'event_type'=>'registration_closed','from_status'=>'registration_open','to_status'=>'registration_closed']);}
 public function test_phase4_window_close_rejects_empty_current_roster_atomically():void
 {
  [$service,$actor]=$this->windowWorkflow(true);
  $service->open($actor,30);

  try{$service->close($actor,30);$this->fail('Expected empty-roster conflict');}
  catch(GradeException$e){$this->assertSame('supplementary_exam_registration_roster_empty',$e->errorCode);$this->assertSame(409,$e->status);}

  $this->assertDatabaseHas('supplementary_exam_periods',['supplementary_exam_period_id'=>30,'status'=>'registration_open']);
  $this->assertDatabaseMissing('supplementary_exam_period_events',['supplementary_exam_period_id'=>30,'event_type'=>'registration_closed']);
 }
 public function test_phase4_window_close_rejects_duplicate_target_within_current_roster_atomically():void
 {
  [$service,$actor]=$this->windowWorkflow(true);
  $this->seedWindowTarget();
  DB::table('courses')->insert(['course_id'=>31]);
  $this->seedWindowOffering(31,30,31);
  $service->open($actor,30);
  $this->seedWindowRegistration(30,30);
  $this->seedWindowRegistration(31,31);

  try{$service->close($actor,30);$this->fail('Expected duplicate-target conflict');}
  catch(GradeException$e){$this->assertSame('supplementary_exam_registration_duplicate_target_conflict',$e->errorCode);$this->assertSame(409,$e->status);}

  $this->assertDatabaseHas('supplementary_exam_periods',['supplementary_exam_period_id'=>30,'status'=>'registration_open']);
  $this->assertDatabaseMissing('supplementary_exam_period_events',['supplementary_exam_period_id'=>30,'event_type'=>'registration_closed']);
  $this->assertSame(2,DB::table('supplementary_exam_registrations')->where('status','registered')->where('current_slot',1)->count());
 }
 public function test_phase4_second_period_close_rejects_target_already_fixed_in_another_period_atomically():void
 {
  [$service,$actor]=$this->windowWorkflow(true);
  $this->seedWindowTarget();
  $service->open($actor,30);
  $this->seedWindowRegistration(30,30);
  $this->assertSame('registration_closed',$service->close($actor,30)->status);

  DB::table('supplementary_exam_periods')->insert(['supplementary_exam_period_id'=>31,'academic_year_id'=>31,'semester_id'=>30,'status'=>'announced','created_at'=>now(),'updated_at'=>now()]);
  $this->seedWindowOffering(31,31,30);
  $service->open($actor,31);
  $this->seedWindowRegistration(31,31);

  try{$service->close($actor,31);$this->fail('Expected cross-period target conflict');}
  catch(GradeException$e){$this->assertSame('supplementary_exam_registration_cross_period_target_conflict',$e->errorCode);$this->assertSame(409,$e->status);}

  $this->assertDatabaseHas('supplementary_exam_periods',['supplementary_exam_period_id'=>30,'status'=>'registration_closed']);
  $this->assertDatabaseHas('supplementary_exam_periods',['supplementary_exam_period_id'=>31,'status'=>'registration_open']);
  $this->assertDatabaseHas('supplementary_exam_period_events',['supplementary_exam_period_id'=>30,'event_type'=>'registration_closed']);
  $this->assertDatabaseMissing('supplementary_exam_period_events',['supplementary_exam_period_id'=>31,'event_type'=>'registration_closed']);
  $this->assertSame(2,DB::table('supplementary_exam_registrations')->where('status','registered')->where('current_slot',1)->count());
 }
 private function windowWorkflow(bool$universityScope):array
 {
  DB::table('users')->insert(['user_id'=>300]);
  DB::table('academic_programs')->insert(['academic_program_id'=>30]);
  DB::table('courses')->insert(['course_id'=>30]);
  DB::table('semesters')->insert(['semester_id'=>30,'semester_order'=>3]);
  DB::table('supplementary_exam_periods')->insert(['supplementary_exam_period_id'=>30,'academic_year_id'=>30,'semester_id'=>30,'status'=>'announced','created_at'=>now(),'updated_at'=>now()]);
  $this->seedWindowOffering(30,30,30);
  $actor=Mockery::mock(User::class)->makePartial();
  $actor->setAttribute('user_id',300);
  $actor->shouldReceive('isRegistrationOfficer')->andReturnTrue();
  $actor->shouldReceive('effectivePermissions')->andReturn(collect([SupplementaryExamRegistrationGovernance::WINDOW]));
  $scope=Mockery::mock(DataScopeService::class);
  $scope->shouldReceive('hasActualUniversityScope')->with($actor)->andReturn($universityScope);
  $eligibility=Mockery::mock(SupplementaryExamEligibilityService::class);
  $eligibility->shouldReceive('evaluationContext')->andReturn([]);
  $eligibility->shouldReceive('evaluate')->andReturn(['eligible'=>true,'eligibility_reason'=>'failed_theoretical']);
  return[new SupplementaryExamRegistrationWindowService($eligibility,$scope),$actor];
 }
 private function seedWindowTarget():void
 {
  DB::table('students')->insert(['student_id'=>30,'academic_program_id'=>30,'created_at'=>now(),'updated_at'=>now()]);
  DB::table('course_offerings')->insert(['course_offering_id'=>30]);
  DB::table('student_course_registrations')->insert(['student_course_registration_id'=>30,'student_id'=>30,'course_offering_id'=>30,'created_at'=>now(),'updated_at'=>now()]);
 }
 private function seedWindowOffering(int$offeringId,int$periodId,int$courseId):void
 {
  DB::table('supplementary_exam_offerings')->insert(['supplementary_exam_offering_id'=>$offeringId,'supplementary_exam_period_id'=>$periodId,'academic_program_id'=>30,'course_id'=>$courseId,'status'=>'open','opened_by_user_id'=>300,'opened_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);
 }
 private function seedWindowRegistration(int$registrationId,int$offeringId):void
 {
  DB::table('supplementary_exam_registrations')->insert(['supplementary_exam_registration_id'=>$registrationId,'supplementary_exam_offering_id'=>$offeringId,'student_id'=>30,'student_course_registration_id'=>30,'status'=>'registered','current_slot'=>1,'eligibility_reason'=>'failed_theoretical','registration_channel'=>'registration_office','registered_by_user_id'=>300,'registered_at'=>now(),'eligibility_checked_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);
 }
 private function workflow(bool$eligible,int$order=3,int$count=1,string$status='registration_open'):array{DB::table('users')->insert(['user_id'=>100]);DB::table('academic_programs')->insert(['academic_program_id'=>1]);DB::table('semesters')->insert(['semester_id'=>1,'semester_order'=>$order]);DB::table('supplementary_exam_periods')->insert(['supplementary_exam_period_id'=>1,'academic_year_id'=>1,'semester_id'=>1,'status'=>$status,'created_at'=>now(),'updated_at'=>now()]);DB::table('students')->insert(['student_id'=>1,'academic_program_id'=>1,'created_at'=>now(),'updated_at'=>now()]);for($i=1;$i<=$count;$i++){DB::table('courses')->insert(['course_id'=>$i]);DB::table('course_offerings')->insert(['course_offering_id'=>$i]);DB::table('supplementary_exam_offerings')->insert(['supplementary_exam_offering_id'=>$i,'supplementary_exam_period_id'=>1,'academic_program_id'=>1,'course_id'=>$i,'status'=>'open','opened_by_user_id'=>100,'opened_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('student_course_registrations')->insert(['student_course_registration_id'=>$i,'student_id'=>1,'course_offering_id'=>$i,'created_at'=>now(),'updated_at'=>now()]);DB::table('supplementary_exam_offering_sources')->insert(['supplementary_exam_offering_id'=>$i,'course_offering_id'=>$i,'created_at'=>now()]);}$actor=Mockery::mock(User::class)->makePartial();$actor->setAttribute('user_id',100);$actor->setAttribute('student_id',1);$actor->shouldReceive('isStudent')->andReturnTrue();$actor->shouldReceive('effectivePermissions')->andReturn(collect([SupplementaryExamRegistrationGovernance::SELF]));$eligibility=Mockery::mock(SupplementaryExamEligibilityService::class);$eligibility->shouldReceive('evaluate')->andReturn(['eligible'=>$eligible,'eligibility_reason'=>$eligible?'failed_theoretical':null]);return[new SupplementaryExamRegistrationService($eligibility,Mockery::mock(DataScopeService::class),Mockery::mock(GradeService::class)),$actor,1,1];}
 private function parents():void{Schema::create('users',fn(Blueprint$t)=>$t->integer('user_id')->autoIncrement());foreach(['academic_programs'=>'academic_program_id','courses'=>'course_id','course_offerings'=>'course_offering_id']as$n=>$id)Schema::create($n,fn(Blueprint$t)=>$t->integer($id)->autoIncrement());Schema::create('semesters',function(Blueprint$t){$t->integer('semester_id')->autoIncrement();$t->integer('semester_order');});Schema::create('student_course_results',function(Blueprint$t){$t->integer('student_course_result_id')->autoIncrement();$t->integer('student_course_registration_id');$t->integer('result_status_id')->nullable();});Schema::create('result_statuses',function(Blueprint$t){$t->integer('result_status_id')->autoIncrement();$t->string('status_code');});Schema::create('registration_statuses',function(Blueprint$t){$t->integer('registration_status_id')->autoIncrement();$t->string('status_code');});Schema::create('approval_statuses',function(Blueprint$t){$t->integer('approval_status_id')->autoIncrement();$t->string('status_code');$t->boolean('is_active')->default(true);});Schema::create('grade_approvals',function(Blueprint$t){$t->integer('grade_approval_id')->autoIncrement();$t->integer('course_offering_id');$t->integer('approval_status_id');$t->timestamps();});Schema::create('grade_components',function(Blueprint$t){$t->integer('grade_component_id')->autoIncrement();$t->integer('course_offering_id');$t->string('component_type');$t->boolean('is_required');});Schema::create('student_grade_components',function(Blueprint$t){$t->integer('student_grade_component_id')->autoIncrement();$t->integer('student_course_registration_id');$t->integer('grade_component_id');$t->decimal('mark')->nullable();});Schema::create('grade_part_approvals',function(Blueprint$t){$t->integer('grade_part_approval_id')->autoIncrement();$t->integer('course_offering_id');$t->string('component_type');$t->string('status');$t->timestamp('submitted_at')->nullable();});Schema::create('permissions',function(Blueprint$t){$t->integer('permission_id')->autoIncrement();$t->string('permission_code')->unique();$t->boolean('is_active');});DB::table('permissions')->insert([['permission_code'=>'supplementary_exams.eligibility.view','is_active'=>1],['permission_code'=>'supplementary_exams.deferrals.self','is_active'=>1]]);}
 private function phase1():void{Schema::create('supplementary_exam_periods',function(Blueprint$t){$t->integer('supplementary_exam_period_id')->autoIncrement();$t->integer('academic_year_id');$t->integer('semester_id');$t->string('status');$t->integer('opened_by_user_id')->nullable();$t->dateTime('opened_at')->nullable();$t->text('decision_note')->nullable();$t->timestamps();$t->unique(['academic_year_id','semester_id'],'period_identity');});Schema::create('supplementary_exam_period_events',function(Blueprint$t){$t->integer('supplementary_exam_period_event_id')->autoIncrement();$t->integer('supplementary_exam_period_id');$t->string('event_type');$t->string('from_status')->nullable();$t->string('to_status');$t->integer('actor_user_id');$t->text('notes')->nullable();$t->timestamp('created_at');$t->index('supplementary_exam_period_id');$t->index('actor_user_id');$t->index(['event_type','to_status']);$t->foreign('supplementary_exam_period_id')->references('supplementary_exam_period_id')->on('supplementary_exam_periods');$t->foreign('actor_user_id')->references('user_id')->on('users');});}
 private function phase2():void{Schema::create('supplementary_exam_offerings',function(Blueprint$t){$t->integer('supplementary_exam_offering_id')->autoIncrement();$t->integer('supplementary_exam_period_id');$t->integer('academic_program_id');$t->integer('course_id');$t->string('status',16);$t->integer('opened_by_user_id');$t->dateTime('opened_at');$t->integer('closed_by_user_id')->nullable();$t->dateTime('closed_at')->nullable();$t->timestamp('created_at');$t->timestamp('updated_at');$t->unique(['supplementary_exam_period_id','academic_program_id','course_id'],'off_identity');$t->foreign('supplementary_exam_period_id')->references('supplementary_exam_period_id')->on('supplementary_exam_periods');$t->foreign('academic_program_id')->references('academic_program_id')->on('academic_programs');$t->foreign('course_id')->references('course_id')->on('courses');$t->foreign('opened_by_user_id')->references('user_id')->on('users');$t->foreign('closed_by_user_id')->references('user_id')->on('users');});Schema::create('supplementary_exam_offering_sources',function(Blueprint$t){$t->integer('supplementary_exam_offering_source_id')->autoIncrement();$t->integer('supplementary_exam_offering_id');$t->integer('course_offering_id');$t->timestamp('created_at');$t->unique(['supplementary_exam_offering_id','course_offering_id'],'source_identity');$t->foreign('supplementary_exam_offering_id')->references('supplementary_exam_offering_id')->on('supplementary_exam_offerings');$t->foreign('course_offering_id')->references('course_offering_id')->on('course_offerings');});Schema::create('supplementary_exam_offering_events',function(Blueprint$t){$t->integer('supplementary_exam_offering_event_id')->autoIncrement();$t->integer('supplementary_exam_offering_id');$t->string('event_type');$t->string('from_status')->nullable();$t->string('to_status');$t->integer('actor_user_id');$t->text('notes')->nullable();$t->timestamp('created_at');$t->index('supplementary_exam_offering_id');$t->index('actor_user_id'